import axios from "axios";
import { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useCart } from "./context/Cartrovider";

const Makepayment = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { product } = location.state || {};
  const { cartItems, clearCart, totalPrice } = useCart();

  const [phone, setPhone] = useState("");
  const [loading, setLoading] = useState("");
  const [success, setSuccess] = useState("");
  const [error, setError] = useState("");

  const img_url = "https://andera.pythonanywhere.com/static/images/";
  const amountToPay = Number(product ? product.product_cost : totalPrice) || 0;

  const payNow = async (e) => {
    e.preventDefault();
    setLoading("Processing payment...");
    setSuccess("");
    setError("");

    try {
      const data = new FormData();
      data.append("amount", amountToPay);
      data.append("phone", phone);

      const response = await axios.post(
        "https://sengi2025.pythonanywhere.com/api/mpesa_payment",
        data
      );

      setLoading("");
      setSuccess(response.data.message);
      setPhone("");

      if (!product) {
        clearCart();
      }
    } catch (error) {
      setLoading("");
      setError("Payment failed. Please try again.");
    }
  };

  if (!product && cartItems.length === 0) {
    return (
      <div className="text-center p-5">
        <h2 className="text-danger">No product selected or cart is empty.</h2>
        <button onClick={() => navigate("/")} className="btn btn-primary mt-3">
          Go to Products
        </button>
      </div>
    );
  }

  return (
    <div className="row mt-4 p-3">
      <div className="col-md-6">
        <div className="card shadow">
          <div className="card-body">
            {product ? (
              <>
                <img
                  src={img_url + product.product_photo}
                  alt=""
                  className="img-fluid rounded"
                />
                <h3 className="text-info mt-3">{product.product_name}</h3>
              </>
            ) : (
              <>
                <h4 className="text-info mb-3">Cart Summary</h4>
                {cartItems.map((item) => (
                  <div key={item.id} className="mb-2 border-bottom pb-2">
                    <p className="mb-1">
                      <b>{item.product_name}</b> (x{item.quantity})
                    </p>
                    <p className="text-muted">
                      KES {(item.product_cost * item.quantity).toFixed(2)}
                    </p>
                  </div>
                ))}
              </>
            )}
          </div>
        </div>
      </div>

      <div className="col-md-6">
        <h1 className="text-danger">KES {amountToPay.toFixed(2)}</h1>
        {product && <p className="text-dark">{product.product_description}</p>}
        <h5 className="text-success">LIPA NA M-PESA</h5>

        <form className="card shadow p-4" onSubmit={payNow}>
          {loading && <p className="text-primary">{loading}</p>}
          {success && <p className="text-success">{success}</p>}
          {error && <p className="text-danger">{error}</p>}

          <input
            type="number"
            value={amountToPay}
            readOnly
            className="form-control mb-3"
          />

          <input
            type="number"
            placeholder="Enter phone (e.g., 2547XXXXXXX)"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
            className="form-control mb-3"
            required
          />

          <button className="btn btn-success w-100">
            <b>Pay Now</b>
          </button>
        </form>
      </div>
    </div>
  );
};

export default Makepayment;
